    private ResponseEntity<Void> redirect(String result){return ResponseEntity.status(303).header("Location",frontendOrigin.replaceAll("/$","")+"/?payment="+result).build();}

    @PostMapping("/support/contact")
    public Map<String,Object> contactSupport(Authentication a,@Valid @RequestBody SupportReq r){
        if(supportEmail==null||supportEmail.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Support email is not configured. Set SUPPORT_EMAIL.");
        User sender=users.findById((String)a.getPrincipal()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Please sign in again"));
        String safeSubject=htmlEscape(r.subject()),safeMessage=htmlEscape(r.message()).replace("\n","<br>");
        integrations.sendEmail(supportEmail,"PaboNaki support: "+safeSubject,"<h2>Customer support message</h2><p><b>From:</b> "+htmlEscape(sender.getName())+" (&lt;"+htmlEscape(sender.getEmail())+"&gt;)</p><p><b>Subject:</b> "+safeSubject+"</p><div>"+safeMessage+"</div>");
        try{integrations.sendEmail(sender.getEmail(),"We received your PaboNaki support message","<p>Hi "+htmlEscape(sender.getName())+",</p><p>We received your message about <b>"+safeSubject+"</b>. Our team will get back to you.</p>");}catch(RuntimeException ignored){}
        return Map.of("message","Your message has been emailed to PaboNaki support.");
    }
    private String htmlEscape(String v){return v==null?"":v.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
    public record SupportReq(@NotBlank @Size(max=100) String subject,@NotBlank @Size(min=8,max=1500) String message){}

